(function(){document.querySelectorAll('.fx-ct').forEach(function(r){
if(!matchMedia('(hover:hover) and (pointer:fine)').matches||matchMedia('(prefers-reduced-motion:reduce)').matches)return;
var N=14,ds=[],px=[],py=[],tx=0,ty=0,run=false,first=true;
for(var i=0;i<N;i++){var e=document.createElement('i');e.className='tr';var t=i/(N-1),s=1.1-t*.8;e.style.setProperty('--t',t);e.style.setProperty('--c',(t*100)+'%');e.style.width=e.style.height=s+'em';e.style.marginLeft=e.style.marginTop=(-s/2)+'em';r.appendChild(e);ds.push(e);px.push(0);py.push(0)}
function draw(){var mv=false,lx=tx,ly=ty;for(var i=0;i<N;i++){var k=.34-i*.015;px[i]+=(lx-px[i])*k;py[i]+=(ly-py[i])*k;if(Math.abs(lx-px[i])>.2||Math.abs(ly-py[i])>.2)mv=true;lx=px[i];ly=py[i];ds[i].style.transform='translate3d('+px[i]+'px,'+py[i]+'px,0)'}
if(mv)requestAnimationFrame(draw);else run=false}
r.addEventListener('pointermove',function(e){if(e.pointerType==='touch')return;var b=r.getBoundingClientRect();tx=e.clientX-b.left;ty=e.clientY-b.top;
if(first){for(var i=0;i<N;i++){px[i]=tx;py[i]=ty}first=false}r.classList.add('vis');if(!run){run=true;requestAnimationFrame(draw)}});
r.addEventListener('pointerleave',function(){r.classList.remove('vis')})})})();
/* touch: tap bursts a ring of dots */
if(!matchMedia('(hover:hover) and (pointer:fine)').matches&&!matchMedia('(prefers-reduced-motion:reduce)').matches&&Element.prototype.animate){document.querySelectorAll('.fx-ct').forEach(function(r){
r.addEventListener('pointerdown',function(e){var b=r.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;for(var k=0;k<9;k++){var d=document.createElement('i');d.className='tr';d.style.setProperty('--t',k/8);d.style.setProperty('--c',(k/8*100)+'%');d.style.width=d.style.height='.7em';d.style.marginLeft=d.style.marginTop='-.35em';d.style.opacity=1;r.appendChild(d);var a=k/9*6.283,dx=Math.cos(a)*46,dy=Math.sin(a)*46;(function(el){el.animate([{transform:'translate3d('+x+'px,'+y+'px,0) scale(1)',opacity:1},{transform:'translate3d('+(x+dx)+'px,'+(y+dy)+'px,0) scale(.2)',opacity:0}],{duration:650,easing:'ease-out'}).onfinish=function(){el.remove()}})(d)}})})}
